section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/csharp-aspnet-core.json",
  "title": "ASP.NET Core Patterns",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "artefact_id",
    "owner",
    "file_path",
    "language",
    "build_passes",
    "tests_passing",
    "rules_checked",
    "version",
    "last_reviewed"
  ],
  "properties": {
    "artefact_id": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9-]+$"
    },
    "owner": {
      "type": "string",
      "minLength": 2
    },
    "file_path": {
      "type": "string"
    },
    "language": {
      "enum": [
        "csharp",
        "java",
        "kotlin",
        "swift",
        "python",
        "typescript",
        "go",
        "bash"
      ]
    },
    "build_passes": {
      "type": "boolean",
      "const": true
    },
    "tests_passing": {
      "type": "integer",
      "minimum": 1
    },
    "rules_checked": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string"
      }
    },
    "design_profile": {
      "type": "object",
      "additionalProperties": false,
      "description": "Optional. When present, pins the design decisions the core rules constrain; every field is checked against the rule that owns it.",
      "required": [
        "layering",
        "dbcontext_lifetime",
        "cancellation_token_propagated",
        "error_format",
        "dto_kind",
        "time_provider",
        "test_db_strategy",
        "pagination",
        "loading",
        "transactions"
      ],
      "properties": {
        "layering": {
          "enum": ["controller-service-repository", "vertical-slice"]
        },
        "dbcontext_lifetime": { "const": "scoped" },
        "cancellation_token_propagated": { "const": true },
        "error_format": { "const": "problem-details-rfc7807" },
        "dto_kind": { "const": "record" },
        "time_provider": { "const": true },
        "test_db_strategy": { "const": "testcontainers" },
        "pagination": { "const": "keyset" },
        "loading": { "const": "eager-include" },
        "transactions": { "const": "explicit" }
      }
    },
    "version": {
      "type": "string",
      "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$"
    },
    "last_reviewed": {
      "type": "string",
      "format": "date"
    }
  }
}
